//! @emoji 🌍️ `dsl_family_geo` — geo/crs family kit for spatial artifacts.

pub use dsl_notation::{print_edge, EdgeLabel, EdgeLink, EdgeNode, EdgeValue};

use dsl_core::{lex, Limits, TextError, TokenKind};

/// @emoji 📍 Parses `lon lat [alt]` tuples.
pub fn parse_point_text(text: &str) -> Result<(f64, f64, Option<f64>), TextError> {
    let limits = Limits::default();
    let nums: Vec<f64> = lex(text, &limits, false)?
        .into_iter()
        .filter(|t| matches!(t.kind, TokenKind::Float | TokenKind::Int))
        .map(|t| t.text.as_str().parse().map_err(|_| TextError::new("bad number", t.span.clone())))
        .collect::<Result<_, _>>()?;
    if nums.len() < 2 {
        return Err(TextError::new("expected at least lon lat", dsl_core::TextSpan::at(1, 1)));
    }
    Ok((nums[0], nums[1], nums.get(2).copied()))
}

//! @emoji 🕸️ `dsl_family_graph` — the graph family notation kit: shared statement piece-parsers
//! for graph-shaped app grammars (trinity, dag, flow, sequence, wires, puzzle2d/3d/5d, space,
//! architect, procedural2d/3d). Builds on `dsl_notation`'s edge/arrow literal and adds the one
//! genuinely graph-family-specific convenience that literal isn't responsible for: node **chains**
//! (`v1 -- v2 -- v3 -- v1`), sugar for a run of anonymous, unlabeled, same-directed edges sharing
//! consecutive endpoints.
//!
//! Re-exports `dsl_notation`'s edge types so an app grammar's handcrafted parser only needs to
//! depend on this one family crate, not both.

pub use dsl_notation::{print_edge, EdgeLabel, EdgeLink, EdgeNode, EdgeValue};

use dsl_core::{lex, Limits, TextError, TokenKind};

//#region 🔖️Chain
/// @emoji ⛓️ A run of nodes joined by uniformly-directed, unlabeled edges: `v1 -- v2 -- v3 -- v1`
/// or `a -> b -> c`. Chains never carry per-edge ids/kinds/properties — an edge that needs any of
/// those breaks the chain and must be written as its own statement (see `expand`/`contract`).
#[derive(Clone, Debug, PartialEq)]
pub struct ChainValue {
    pub nodes: Vec<EdgeNode>,
    pub directed: bool,
}

impl ChainValue {
    /// @emoji 📤️ Lowers a chain into the individual edges it's sugar for — `n-1` edges over `n`
    /// nodes — so the semantic model only ever needs to store plain edges, never chain structure.
    pub fn expand(&self) -> Vec<EdgeValue> {
        self.nodes
            .windows(2)
            .map(|pair| EdgeValue { from: pair[0].clone(), link: Some(EdgeLink { directed: self.directed, label: EdgeLabel::default(), to: pair[1].clone() }) })
            .collect()
    }
}

/// @emoji 📥️ The printer-side inverse of `expand`: contracts a maximal PREFIX of `edges` that
/// shares one direction, carries no labels, and threads consecutive endpoints (each edge's `to`
/// equals the next edge's `from`) into one `ChainValue`, returning how many edges it consumed.
/// Returns `None` if `edges` doesn't even start such a run (the caller should print `edges[0]` as
/// a standalone statement instead and retry `contract` on the remainder).
pub fn contract(edges: &[EdgeValue]) -> Option<(ChainValue, usize)> {
    let first_link = edges.first()?.link.as_ref()?;
    if !first_link.label.is_empty() {
        return None;
    }
    let directed = first_link.directed;
    let mut nodes = vec![edges[0].from.clone(), first_link.to.clone()];
    let mut consumed = 1;
    for edge in &edges[1..] {
        let Some(link) = &edge.link else { break };
        if link.directed != directed || !link.label.is_empty() || edge.from != *nodes.last().unwrap() {
            break;
        }
        nodes.push(link.to.clone());
        consumed += 1;
    }
    if consumed < 2 {
        return None;
    }
    Some((ChainValue { nodes, directed }, consumed))
}

fn node_text(node: &EdgeNode) -> String {
    let mut s = node.id.clone();
    if let Some(kind) = &node.kind {
        s.push(':');
        s.push_str(kind);
    }
    if let Some(port) = &node.port {
        s.push('@');
        s.push_str(port);
    }
    s
}

/// @emoji 🖨️ Canonical printer for one chain: `v1--v2--v3` (directed: `v1->v2->v3`) — matches the
/// existing no-space style of plain unlabeled edges, since a chain of unlabeled edges never hits
/// the label-adjacent dash-fusion issue `dsl_notation::print_edge` documents.
pub fn print_chain(chain: &ChainValue) -> String {
    let joiner = if chain.directed { "->" } else { "--" };

//! @emoji 🧑‍🍳️ `dsl_family_recipe` — the recipe family notation kit, shared by `process3d`,
//! `playbook`, and `shome`: ordered typed-call steps, `name: target(args)` — e.g.
//! `step-1: state.set(counter 0)`. Deliberately NOT built on `dsl_schema::RecordLayout::Call`:
//! that layout fixes both the separator (`=`) and the call target (`RecordSpec.keyword`) at spec-
//! declaration time, which fits a construction chain where every statement calls the same function
//! (`extrude = brep.solid.extrude(...)`) but not a recipe step, where each step's target varies
//! (`state.set`, `state.get`, `math.add`, ...) and the separator is `:`. Built directly on
//! `dsl_core::lex`, matching `dsl_notation`/`dsl_family_graph`/`dsl_family_catalog`'s pattern.

use dsl_core::{lex, Limits, TextError, TextSpan, TokenKind};

//#region 🔖️Step
/// @emoji 🪜️ One recipe step: `name: target(arg1 arg2 ...)`. Arguments are positional only in
/// this v1 (bare `Ident`/`Int`/`Float`/`Text` tokens, printed as their own text) — `key=value`
/// keyed arguments are not yet supported (a real, documented gap, not silently dropped).
#[derive(Clone, Debug, PartialEq)]
pub struct RecipeStep {
    pub name: String,
    pub target: String,
    pub args: Vec<String>,
}

struct Cursor {
    tokens: Vec<dsl_core::SpannedToken>,
    pos: usize,
}

impl Cursor {
    fn peek(&self) -> &dsl_core::SpannedToken {
        &self.tokens[self.pos.min(self.tokens.len() - 1)]
    }

    fn advance(&mut self) -> dsl_core::SpannedToken {
        let token = self.tokens[self.pos.min(self.tokens.len() - 1)].clone();
        if self.pos < self.tokens.len() - 1 {
            self.pos += 1;
        }
        token
    }

    fn expect(&mut self, kind: TokenKind) -> Result<dsl_core::SpannedToken, TextError> {
        if self.peek().kind == kind {
            Ok(self.advance())
        } else {
            Err(TextError::new(format!("expected {kind:?}, found {:?}", self.peek().kind), self.peek().span))
        }
    }

    fn span(&self) -> TextSpan {
        self.peek().span
    }
}

fn arg_text(token: &dsl_core::SpannedToken) -> Result<String, TextError> {
    match token.kind {
        TokenKind::Ident | TokenKind::Int | TokenKind::Float => Ok(token.text.as_str().to_string()),
        TokenKind::Text => Ok(format!("\"{}\"", dsl_core::escape_text(&token.text.as_str()))),
        other => Err(TextError::new(format!("expected an argument, found {other:?}"), token.span)),
    }
}

/// @emoji 🔌️ Parses one standalone recipe step: `name: target(arg1 arg2)`. `target` may be a
/// dotted call path (`state.set`) since `.` is `dsl_core` ident-continue — it lexes as one `Ident`.
pub fn parse_step_text(text: &str) -> Result<RecipeStep, TextError> {
    let limits = Limits::default();
    // Keeps the `Eof` sentinel (only trivia is filtered) — `Cursor::advance`'s clamp-at-last-index
    // logic needs a real final token to land on and stay at once input is exhausted; dropping it
    // makes `peek()` re-return whatever the last REAL token was forever instead of signaling Eof.
    let tokens: Vec<_> = lex(text, &limits, false)?.into_iter().filter(|t| !t.kind.is_trivia()).collect();
    let mut cursor = Cursor { tokens, pos: 0 };

    let name = cursor.expect(TokenKind::Ident)?.text.as_str().to_string();
    cursor.expect(TokenKind::Colon)?;
    let target = cursor.expect(TokenKind::Ident)?.text.as_str().to_string();
    cursor.expect(TokenKind::LParen)?;
    let mut args = Vec::new();
    while cursor.peek().kind != TokenKind::RParen {
        args.push(arg_text(&cursor.advance())?);
    }
    cursor.expect(TokenKind::RParen)?;

//! @emoji 🎬️ `dsl_family_scene` — scene/layout family kit: layer stacks and shared edge notation.

pub use dsl_notation::{print_edge, EdgeLabel, EdgeLink, EdgeNode, EdgeValue};

use dsl_core::{lex, Limits, TextError, TokenKind};

/// @emoji 📐️ Parses `id@x y [z]` layer placement literals.
pub fn parse_layer_anchor_text(text: &str) -> Result<(String, f64, f64, Option<f64>), TextError> {
    let limits = Limits::default();
    let tokens: Vec<_> = lex(text, &limits, false)?.into_iter().filter(|t| !t.kind.is_trivia() && t.kind != TokenKind::Eof).collect();
    let id = tokens.first().ok_or_else(|| TextError::new("expected layer id", dsl_core::TextSpan::at(1, 1)))?;
    if id.kind != TokenKind::Ident {
        return Err(TextError::new("expected layer id", id.span.clone()));
    }
    if tokens.get(1).map(|t| t.kind) != Some(TokenKind::At) {
        return Err(TextError::new("expected `@` after layer id", id.span.clone()));
    }
    let x = tokens.get(2).ok_or_else(|| TextError::new("expected x", id.span.clone()))?;
    let y = tokens.get(3).ok_or_else(|| TextError::new("expected y", id.span.clone()))?;
    if !matches!(x.kind, TokenKind::Float | TokenKind::Int) || !matches!(y.kind, TokenKind::Float | TokenKind::Int) {
        return Err(TextError::new("expected numeric x y", y.span.clone()));
    }
    let xf: f64 = x.text.as_str().parse().map_err(|_| TextError::new("bad x", x.span.clone()))?;
    let yf: f64 = y.text.as_str().parse().map_err(|_| TextError::new("bad y", y.span.clone()))?;
    let z = tokens.get(4).and_then(|t| {
        if matches!(t.kind, TokenKind::Float | TokenKind::Int) {
            t.text.as_str().parse().ok()
        } else {
            None
        }
    });
    Ok((id.text.as_str().to_string(), xf, yf, z))
}

