                use std::os::windows::fs::FileExt;
                guard.seek_read(buf, offset).map_err(io_err)
            }
            #[cfg(not(any(unix, windows)))]
            {
                use std::io::{Read, Seek, SeekFrom};
                let mut guard = guard;
                guard.seek(SeekFrom::Start(offset)).map_err(io_err)?;
                guard.read(buf).map_err(io_err)
            }
        }
